#!/bin/sh
# Reference CAdES signatures made by AutoFirma 1.9 over doc.txt. They change on
# every run (signing time), so they are not regenerated by this script.
#
# autofirma-explicit-{rsa,ec}.csig and autofirma-implicit-age-rsa.csig (implicit,
# AGE v1.9 policy) were made with AutoFirma's CLI (autofirma.jar sign -format cades).
#
# Co-signature (RSA) of the implicit one, then counter-signed (tree) with EC,
# with AutoFirma's CAdES signer:
#
#   J="java -cp /usr/lib/Autofirma/autofirma.jar ../../../tools/AfirmaMulti.java"
#   $J ../certs/rsa.p12 cosign cades autofirma-implicit-age-rsa.csig autofirma-cosign-rsa.csig
#   $J ../certs/ec.p12 countersign-tree cades autofirma-cosign-rsa.csig autofirma-countersign-ec.csig
#
# Under the VS Code snap, run java with a clean environment (env -i PATH=/usr/bin:/bin java ...).
exit 0
